const $=s=>document.querySelector(s), KEY='scriptroom.editor.v1';
const labels={scene:'Scene heading',action:'Action',character:'Character',dialogue:'Dialogue',parenthetical:'Parenthetical',shot:'Shot',transition:'Transition'};
const sample=[['scene','EXT. COASTAL ROAD - DUSK'],['action','The last of the daylight hangs over the water. A narrow road cuts through the cliffs, empty except for a faded blue station wagon.'],['action','Inside, a map unfolds across the passenger seat. Someone has circled a town at the very edge of the paper.'],['scene','INT. STATION WAGON - CONTINUOUS'],['action','ELLA, 32, drives with the window down. Her younger brother, BEN, studies the map as if it might change its mind.'],['character','BEN'],['dialogue',"You know there's a faster way."],['character','ELLA'],['dialogue',"I know."],['parenthetical','(a beat)'],['dialogue',"That's not why we're here."],['action','Ben looks out at the sea. On the horizon, a lighthouse blinks once. Then darkness.'],['character','BEN'],['dialogue',"You think he still keeps it on?"],['action',"Ella doesn't answer. She turns the radio down, although nothing is playing."],['transition','CUT TO:'],['scene','EXT. LIGHTHOUSE - NIGHT'],['action','A porch light warms the steps of a weather-beaten house. Beyond it, the lighthouse rises into the fog.'],['action','Ella stops at the gate. A handwritten sign reads: BACK BEFORE DARK.'],['character','ELLA'],['parenthetical','(to herself)'],['dialogue',"You're late."],['action','From somewhere inside, a kettle begins to whistle.']];
let current=null, saveTimer, layoutTimer, toastTimer;
function toast(t){$('#toast').textContent=t;$('#toast').style.opacity=1;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.opacity=0,3000)}
function block(type,text='',id=crypto.randomUUID()){const b=document.createElement('div');b.className='block';b.contentEditable='true';b.spellcheck=true;b.dataset.type=type;b.dataset.id=id;b.dataset.placeholder=labels[type];b.setAttribute('role','textbox');b.setAttribute('aria-label',labels[type]);b.textContent=text;return b}
function page(){const p=document.createElement('article');p.className='page';const c=document.createElement('div');c.className='page-content';p.append(c);$('#pages').append(p);return c}
function all(){return [...document.querySelectorAll('.block')]}
function paginate(){const blocks=all();const active=document.activeElement;const sel=window.getSelection();const range=sel.rangeCount?sel.getRangeAt(0).cloneRange():null;let c=page();const old=[...$('#pages').children].slice(0,-1);for(const b of blocks){c.append(b);if(c.offsetHeight>864&&c.children.length>1){c=page();c.append(b)}}old.forEach(p=>p.remove());[...$('#pages').children].forEach((p,i)=>{if(i){const n=document.createElement('span');n.className='page-number';n.textContent=(i+1)+'.';p.append(n)}});if(active?.classList.contains('block')){active.focus({preventScroll:true});if(range){sel.removeAllRanges();sel.addRange(range)}}updateOutline();stats()}
function updateOutline(){const nav=$('#outline');nav.replaceChildren();all().filter(b=>b.dataset.type==='scene').forEach((b,i)=>{const button=document.createElement('button');button.className='scene-link'+(current===b?' selected':'');const num=document.createElement('span');num.className='num';num.textContent=String(i+1).padStart(2,'0');const label=document.createElement('span');const title=document.createElement('strong');title.textContent=b.textContent||'UNTITLED SCENE';const sub=document.createElement('small');sub.textContent='Page '+([...$('#pages').children].indexOf(b.closest('.page'))+1);label.append(title,sub);button.append(num,label);button.onclick=()=>{b.focus();b.scrollIntoView({behavior:'smooth',block:'center'})};nav.append(button)})}
function stats(){const text=all().map(b=>b.textContent).join(' ').trim();$('#counts').textContent=`${$('#pages').children.length} ${$('#pages').children.length===1?'page':'pages'}   ·   ${text?text.split(/\s+/).length:0} words`;$('.project-name').firstChild.textContent=$('#title').textContent+' ';$('.breadcrumb').firstChild.textContent=$('#title').textContent+' ';document.title=$('#title').textContent+' — Scriptroom'}
function save(){try{localStorage.setItem(KEY,JSON.stringify({title:$('#title').textContent,blocks:all().map(b=>({type:b.dataset.type,text:b.textContent,id:b.dataset.id}))}));$('#saveStatus').innerHTML='<i></i> Saved locally'}catch(e){$('#saveStatus').textContent='Not saved — export a copy';toast('Storage is unavailable. Export a copy to keep your work.')}}
function changed(){ $('#saveStatus').textContent='Saving…';clearTimeout(saveTimer);saveTimer=setTimeout(save,250);clearTimeout(layoutTimer);layoutTimer=setTimeout(paginate,500);stats() }
function setType(b,type){b.dataset.type=type;b.dataset.placeholder=labels[type];b.setAttribute('aria-label',labels[type]);$('#element').value=type;$('#currentElement').textContent=labels[type];changed()}
function caret(b,end=false){b.focus();const r=document.createRange();r.selectNodeContents(b);r.collapse(!end);const s=getSelection();s.removeAllRanges();s.addRange(r)}
$('#pages').addEventListener('focusin',e=>{if(!e.target.matches('.block'))return;current=e.target;$('#element').value=current.dataset.type;$('#currentElement').textContent=labels[current.dataset.type];updateOutline()});
$('#pages').addEventListener('input',changed);
$('#pages').addEventListener('paste',e=>{if(!e.target.matches('.block'))return;e.preventDefault();document.execCommand('insertText',false,e.clipboardData.getData('text/plain'))});
$('#pages').addEventListener('keydown',e=>{const b=e.target;if(!b.matches('.block'))return;if(e.key==='Tab'){e.preventDefault();const types=Object.keys(labels);setType(b,types[(types.indexOf(b.dataset.type)+(e.shiftKey?types.length-1:1))%types.length]);return}if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();const sel=getSelection();if(!sel.rangeCount)return;const r=sel.getRangeAt(0);r.deleteContents();const trailing=r.cloneRange();trailing.setEnd(b,b.childNodes.length);const tail=trailing.extractContents();const next={scene:'action',action:'action',character:'dialogue',dialogue:'character',parenthetical:'dialogue',shot:'action',transition:'scene'};const n=block(next[b.dataset.type],tail.textContent);b.after(n);caret(n);changed()}if(e.key==='Backspace'&&!b.textContent&&all().length>1){e.preventDefault();const prev=all()[all().indexOf(b)-1];const next=all()[all().indexOf(b)+1];b.remove();caret(prev||next,true);changed()}});
$('#element').addEventListener('change',e=>{if(!current)current=all()[0];setType(current,e.target.value);current.focus()});
$('#title').addEventListener('input',changed);$('#title').addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();$('#title').blur()}});$('#title').addEventListener('blur',()=>{if(!$('#title').textContent.trim())$('#title').textContent='Untitled screenplay';stats();save()});
function append(type){const b=block(type);$('#pages').lastElementChild.querySelector('.page-content').append(b);paginate();caret(b);b.scrollIntoView({behavior:'smooth',block:'center'});changed()}
$('#addScene').onclick=()=>append('scene');$('#addBlock').onclick=()=>append('action');
$('#zoom').onchange=e=>{$('#pages').style.zoom=e.target.value;$('.paper-caption').style.width=(816*Number(e.target.value))+'px'};
$('#focus').onclick=()=>{document.body.classList.toggle('focus');$('#focus span').textContent=document.body.classList.contains('focus')?'Exit focus':'Focus'};
function modal(html){$('#modalContent').innerHTML=html;$('#modal').showModal()}
$('.close').onclick=()=>$('#modal').close();$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))$('#modal').close()});
$('#help').onclick=()=>modal('<div class="eyebrow">MAKE YOURSELF AT HOME</div><h2>Just keep writing.</h2><p>Your draft saves in this browser. Export a copy whenever you need one.</p><div class="shortcut-row"><span>Next element</span><kbd>Enter</kbd></div><div class="shortcut-row"><span>Line break</span><kbd>Shift + Enter</kbd></div><div class="shortcut-row"><span>Change element type</span><kbd>Tab / Shift + Tab</kbd></div><div class="shortcut-row"><span>Save locally</span><kbd>⌘ / Ctrl + S</kbd></div><p>Letter paper · 12 pt Courier · 6 lines per inch.<br>Margins: 1.5″ left; 1″ top, right, and bottom.</p>');
function download(text,ext,type){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([text],{type}));a.href=url;a.download=($('#title').textContent.replace(/[^a-z0-9 _-]/gi,'')||'screenplay')+ext;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);$('#modal').close();toast('Your screenplay has been exported.')}
$('#export').onclick=()=>{modal('<div class="eyebrow">TAKE YOUR STORY WITH YOU</div><h2>Export screenplay</h2><p>Create a copy of your current working draft.</p><button class="export-option" id="pdf">Print / Save as PDF ↗<small>Formatted US Letter pages. Select 100% scale and turn off browser headers.</small></button><button class="export-option" id="fountain">Fountain file ↓<small>Plain-text screenplay for other writing apps.</small></button><button class="export-option" id="backup">Draft backup ↓<small>JSON with scene and element identities.</small></button>');$('#pdf').onclick=()=>{$('#modal').close();paginate();window.print()};$('#fountain').onclick=()=>{let out='Title: '+$('#title').textContent+'\n\n';all().forEach(b=>{const t=b.dataset.type;let s=b.textContent;if(['scene','shot','character','transition'].includes(t))s=s.toUpperCase();if(t==='scene')s='.'+s;if(t==='character')s='@'+s;if(t==='transition')s='> '+s;if(t==='action'||t==='shot')s='!'+s;if(t==='parenthetical'&&!s.startsWith('('))s='('+s+')';out+=(['dialogue','parenthetical'].includes(t)?'':'\n')+s+'\n'});download(out,'.fountain','text/plain')};$('#backup').onclick=()=>download(JSON.stringify({title:$('#title').textContent,blocks:all().map(b=>({id:b.dataset.id,type:b.dataset.type,text:b.textContent}))},null,2),'.json','application/json')};
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key==='s'){e.preventDefault();save();toast('Draft saved on this device.')}if(e.key==='Escape'&&document.body.classList.contains('focus'))$('#focus').click()});
window.addEventListener('pagehide',save);document.addEventListener('visibilitychange',()=>{if(document.hidden)save()});
let data;try{data=JSON.parse(localStorage.getItem(KEY));if(!Array.isArray(data?.blocks)||!data.blocks.length)data=null}catch{}const c=page();if(data){$('#title').textContent=data.title;data.blocks.forEach(b=>c.append(block(labels[b.type]?b.type:'action',String(b.text||''),b.id)))}else sample.forEach(([type,text])=>c.append(block(type,text)));paginate();if(window.innerWidth<750){$('#zoom').value='.65';$('#pages').style.zoom=Math.min(.65,(window.innerWidth-26)/816)}
